import { Database } from 'bun:sqlite';

// ✅ Built-in: Zero npm dependencies, pre-compiled with WAL mode support
const db = new Database('app.db', { create: true });

// Run migrations or pragmas:
db.run('PRAGMA journal_mode = WAL;');

const query = db.query('SELECT id, name FROM users WHERE age > $age');
const users = query.all({ $age: 21 });
console.log(users);
